def pick_model(registry: ModelRegistry, needs_tools: bool) -> str:
    for handle in registry.list_handles():
        spec = registry.resolve(handle)
        if spec.supports_tools == needs_tools and spec.context_window_tokens >= 200_000:
            return spec.handle
    raise LookupError("no model with required capability")

def retrieve_context(store: VectorStore, tenant: str, qvec: list[float]) -> list[str]:
    hits = store.search(tenant, qvec, top_k=5, filter={"kind": "policy"})
    return [h.doc_id for h in hits if h.score > 0.75]

def check_prompt(guards: list[InputGuardrail], text: str) -> str:
    for g in guards:
        d = g.evaluate(text, {"user_role": "customer"})
        if d.action == "block":
            raise PermissionError(f"{g.name}: {d.reason}")
        if d.action == "redact" and d.redacted_text is not None:
            text = d.redacted_text
    return text

def post_process(guards: list[OutputGuardrail], raw: str, schema: str) -> str:
    current = raw
    for g in guards:
        v = g.evaluate(current, schema)
        if v.action == "block":
            raise ValueError(f"{g.name}: {v.reason}")
        if v.action == "rewrite" and v.replacement is not None:
            current = v.replacement
    return current

def propose_refund(cp: HumanCheckpoint, payload: dict[str, str]) -> dict[str, str]:
    ticket = cp.request(payload, required_role="finance_lead")
    decision = cp.await_decision(ticket, timeout_seconds=3600)
    if decision.verdict == "rejected":
        raise PermissionError("refund denied")
    return decision.edited_payload or payload

def cached_completion(cache: ResponseCache, prompt_hash: str, tenant: str) -> str | None:
    key = type("K", (), {"mode": "exact", "value": prompt_hash, "namespace": tenant})()
    return cache.lookup(key)

def call_planner(router: ModelRouter, policy: RoutePolicy, tenant: str) -> str:
    handle = router.choose(policy, tenant)
    return handle

def dispatch(schema: ToolSchema, raw_args: dict[str, object], scopes: set[str]) -> dict[str, object]:
    missing = set(schema.required_scopes) - scopes
    if missing:
        raise PermissionError(f"missing scopes: {missing}")
    return schema.validate_arguments(raw_args)

def guarded_call(guard: BudgetGuard, tenant: str, feature: str, est: int) -> str:
    v = guard.check(tenant, feature, est)
    if v.action == "deny":
        raise PermissionError(f"budget exhausted (window {v.window_seconds}s)")
    return "allowed"
